import { Injectable, Injector } from "@angular/core";
import { Overlay } from "@angular/cdk/overlay";
import { ComponentPortal, ComponentType } from "@angular/cdk/portal";
import { SwDialogRef } from "../models/dialog.ref";
import { SW_DIALOG_DATA } from "../sw-dialog.constant";
import { SwDialogConfig } from "../models/dialog.config";

@Injectable()
export class SwDialogService {
    constructor(
        private overlay: Overlay,
        private injector: Injector
    ) {}

    private createInjector<I,O>(data: I | null, swDialogRef: SwDialogRef<O>): Injector {
        const injector = Injector.create({
            providers: [
                {
                    provide: SW_DIALOG_DATA,
                    useValue: data
                },
                {
                    provide: SwDialogRef,
                    useValue: swDialogRef
                }
            ],
            parent: this.injector
        })
        return injector;
    }

    open<I, O>(component: ComponentType<unknown>, config: SwDialogConfig<I> = {}): SwDialogRef<O> {
        let positionStrategy 
            = this.overlay.position().global().centerHorizontally().centerVertically();

        const ref = this.overlay.create({
            positionStrategy,
            hasBackdrop: true,  
        })

        const swDialogRef = new SwDialogRef<O>(ref);

        const portal = new ComponentPortal(
            component, 
            null, 
            this.createInjector<I,O>(config.data || null, swDialogRef)
        );

        ref.attach(portal);

        ref.backdropClick().subscribe(_ => {
            swDialogRef.close(null);
        })

        return swDialogRef;
    }
}

import { Overlay, OverlayRef } from "@angular/cdk/overlay";
import { ComponentPortal, PortalInjector } from "@angular/cdk/portal";
import { Injectable, InjectionToken, Injector } from "@angular/core";
import { SwToastHostComponent } from "../components/sw-toast-host/sw-toast-host.component";
import { SwToastConfig, SwToastOverlayConfig, SwToastStatus } from "../models/sw-toast.config";
import { SW_TOAST_DATA } from "../sw-toast.constants";

@Injectable()
export class SwToastService {

    constructor(
        private overlay: Overlay,
        private injector: Injector
    ) {}

    private createToastMessage(status: SwToastStatus, config: SwToastConfig): OverlayRef {
        const positionStrategy = this.overlay.position().global().top('80vh').left('75vw');
        const overlayRef = this.overlay.create({
            positionStrategy
        })
        const injectionTokens = new WeakMap<InjectionToken<string>, SwToastOverlayConfig>();
        injectionTokens.set(SW_TOAST_DATA, {
            ...config, status
        })
        const toastPortalInjector = new PortalInjector(this.injector, injectionTokens);
        const componentPortal = new ComponentPortal(SwToastHostComponent, null, toastPortalInjector);
        overlayRef.attach(componentPortal);
        this.initateClearToast(overlayRef, config.closeAfter);
        return overlayRef;
    }

    success(config: SwToastConfig) {
        this.createToastMessage(SwToastStatus.SUCCESS, config);
    }

    warn(config: SwToastConfig) {
        this.createToastMessage(SwToastStatus.WARN, config);
    }

    error(config: SwToastConfig) {
        this.createToastMessage(SwToastStatus.ERROR, config);
    }

    

    private initateClearToast(ref: OverlayRef, closeAfter?: number) {
        setTimeout(() => {
            ref.dispose();
        }, closeAfter || 3000);
    }
}

